cypress_script:
describe('Add and Remove Elements', () => {
  it('should add an element when the button is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('button').contains('Add Element').click();
    cy.get('#elements').children().should('have.length', 1);
  });

  it('should not add more elements if button is not clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/add_remove_elements/');
    cy.get('#elements').children().should('have.length', 0);
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Add and Remove Elements', () => {
  test('should add an element when the button is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    await page.click('button:has-text("Add Element")');
    const elements = await page.locator('#elements').count();
    expect(elements).toBe(1);
  });

  test('should not add more elements if button is not clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
    const elements = await page.locator('#elements').count();
    expect(elements).toBe(0);
  });
});
